            { "Horizontal FOV in Over-the-Shoulder only (degrees, 4:3 basis). 71.1 = original.",
                new[]{ "FOV horizontal solo en vista sobre el hombro (grados, base 4:3). 71.1 = original.", "FOV horizontal só na visão sobre o ombro (graus, base 4:3). 71.1 = original.", "FOV horizontal en vue par-dessus l'épaule uniquement (degrés, base 4:3). 71.1 = d'origine.", "Horizontales FOV nur in der Über-die-Schulter-Ansicht (Grad, 4:3-Basis). 71.1 = Original.", "FOV orizzontale solo nella visuale sopra la spalla (gradi, base 4:3). 71.1 = originale.", "肩越し視点でのみ使う水平FOV(度、4:3基準)。71.1 = オリジナル。", "仅用于越肩视角的水平视野(度，4:3 基准)。71.1 = 原版。", "Горизонтальный FOV только в виде из-за плеча (градусы, база 4:3). 71.1 = оригинал.", "Poziome FOV tylko w widoku zza ramienia (stopnie, podstawa 4:3). 71.1 = oryginał." } },
            { "How far the Thirdperson camera zooms in while aiming. 100 = original, 200 = closest, 0 = none, negative = pull back.",
                new[]{ "Cuánto se acerca la cámara en 3ª persona al apuntar. 100 = original, 200 = lo máximo, 0 = nada, negativo = se aleja.", "Quanto a câmera em 3ª pessoa se aproxima ao mirar. 100 = original, 200 = o máximo, 0 = nada, negativo = se afasta.", "Zoom de la caméra 3e personne pendant la visée. 100 = d'origine, 200 = au plus près, 0 = aucun, négatif = recul.", "Wie weit die Third-Person-Kamera beim Zielen heranzoomt. 100 = Original, 200 = am nächsten, 0 = kein Zoom, negativ = zurückziehen.", "Quanto si avvicina la telecamera in terza persona mentre miri. 100 = originale, 200 = il massimo, 0 = nessuno, negativo = si allontana.", "三人称カメラで構えたときのズーム量。100 = オリジナル、200 = 最大、0 = なし、負の値 = 引く。", "第三人称镜头瞄准时的推近程度。100 = 原版，200 = 最近，0 = 不缩放，负值 = 拉远。", "Насколько приближается камера от 3-го лица при прицеливании. 100 = оригинал, 200 = максимум, 0 = нет, отрицательное = отдаление.", "Jak mocno kamera trzeciej osoby przybliża przy celowaniu. 100 = oryginał, 200 = najbliżej, 0 = brak, ujemne = oddala." } },
            { "How far the Over-the-Shoulder camera zooms in while aiming. 100 = original, 200 = closest, 0 = none, negative = pull back.",
                new[]{ "Cuánto se acerca la cámara sobre el hombro al apuntar. 100 = original, 200 = lo máximo, 0 = nada, negativo = se aleja.", "Quanto a câmera sobre o ombro se aproxima ao mirar. 100 = original, 200 = o máximo, 0 = nada, negativo = se afasta.", "Zoom de la caméra par-dessus l'épaule pendant la visée. 100 = d'origine, 200 = au plus près, 0 = aucun, négatif = recul.", "Wie weit die Über-die-Schulter-Kamera beim Zielen heranzoomt. 100 = Original, 200 = am nächsten, 0 = kein Zoom, negativ = zurückziehen.", "Quanto si avvicina la telecamera sopra la spalla mentre miri. 100 = originale, 200 = il massimo, 0 = nessuno, negativo = si allontana.", "肩越しカメラで構えたときのズーム量。100 = オリジナル、200 = 最大、0 = なし、負の値 = 引く。", "越肩镜头瞄准时的推近程度。100 = 原版，200 = 最近，0 = 不缩放，负值 = 拉远。", "Насколько приближается камера из-за плеча при прицеливании. 100 = оригинал, 200 = максимум, 0 = нет, отрицательное = отдаление.", "Jak mocno kamera zza ramienia przybliża przy celowaniu. 100 = oryginał, 200 = najbliżej, 0 = brak, ujemne = oddala." } },
            { "Mouse look speed for the Thirdperson, Over-the-Shoulder and First-person cameras (1.0 = default).",
                new[]{ "Velocidad de la cámara con el ratón en 3ª persona, sobre el hombro y 1ª persona (1.0 = predeterminado).", "Velocidade da câmera com o mouse em 3ª pessoa, sobre o ombro e 1ª pessoa (1.0 = padrão).", "Vitesse de visée à la souris pour les caméras 3e personne, épaule et 1re personne (1.0 = défaut).", "Maus-Blickgeschwindigkeit für Third-Person-, Schulter- und Ego-Kamera (1.0 = Standard).", "Velocità della visuale con il mouse per le telecamere in terza persona, sopra la spalla e in prima persona (1.0 = predefinito).", "三人称・肩越し・一人称カメラのマウス視点速度(1.0 = 既定)。", "第三人称、越肩和第一人称镜头的鼠标视角速度(1.0 = 默认)。", "Скорость обзора мышью для камер от 3-го лица, из-за плеча и от 1-го лица (1.0 = по умолчанию).", "Prędkość rozglądania myszą dla kamer trzeciej osoby, zza ramienia i pierwszej osoby (1.0 = domyślnie)." } },
            { "Right-stick look speed for the Thirdperson, Over-the-Shoulder and First-person cameras (1.0 = default).",
                new[]{ "Velocidad de la cámara con el stick derecho en 3ª persona, sobre el hombro y 1ª persona (1.0 = predeterminado).", "Velocidade da câmera com o analógico direito em 3ª pessoa, sobre o ombro e 1ª pessoa (1.0 = padrão).", "Vitesse de visée au stick droit pour les caméras 3e personne, épaule et 1re personne (1.0 = défaut).", "Blickgeschwindigkeit des rechten Sticks für Third-Person-, Schulter- und Ego-Kamera (1.0 = Standard).", "Velocità della visuale con lo stick destro per le telecamere in terza persona, sopra la spalla e in prima persona (1.0 = predefinito).", "三人称・肩越し・一人称カメラの右スティック視点速度(1.0 = 既定)。", "第三人称、越肩和第一人称镜头的右摇杆视角速度(1.0 = 默认)。", "Скорость обзора правым стиком для камер от 3-го лица, из-за плеча и от 1-го лица (1.0 = по умолчанию).", "Prędkość rozglądania prawym drążkiem dla kamer trzeciej osoby, zza ramienia i pierwszej osoby (1.0 = domyślnie)." } },
            { "Walk by default and sprint only while Run is held, like the classic controls. Off = pushing the stick far also sprints.",
                new[]{ "Camina por defecto y corre solo mientras mantienes Correr, como en los controles clásicos. Desactivado = empujar el stick a fondo también corre.", "Anda por padrão e só corre enquanto Correr estiver pressionado, como nos controles clássicos. Desligado = empurrar o analógico até o fim também corre.", "Marche par défaut et ne court qu'en maintenant Courir, comme les contrôles classiques. Désactivé = pousser le stick à fond fait aussi courir.", "Standardmäßig gehen und nur bei gehaltener Rennen-Taste sprinten, wie bei der klassischen Steuerung. Aus = Stick weit drücken sprintet ebenfalls.", "Cammina di default e corri solo tenendo premuto Corri, come nei controlli classici. Disattivato = spingere a fondo lo stick fa anche correre.", "通常は歩き、ダッシュボタンを押している間だけ走ります(クラシック操作と同じ)。オフ = スティックを大きく倒しても走ります。", "默认步行，仅在按住奔跑键时冲刺，与经典操作相同。关闭 = 将摇杆推到底也会冲刺。", "По умолчанию шаг, бег — только при удержании «Бега», как в классическом управлении. Выкл. = сильное отклонение стика тоже включает бег.", "Domyślnie chód, bieg tylko przy przytrzymaniu Bieg, jak w klasycznym sterowaniu. Wył. = mocne wychylenie drążka też uruchamia bieg." } },
            { "Thirdperson / Over-the-Shoulder: pull the camera in when a wall gets between it and Harry. Off = the camera can pass through walls.",
                new[]{ "3ª persona / sobre el hombro: acerca la cámara cuando una pared se interpone entre ella y Harry. Desactivado = la cámara puede atravesar paredes.", "3ª pessoa / sobre o ombro: aproxima a câmera quando uma parede fica entre ela e Harry. Desligado = a câmera pode atravessar paredes.", "3e personne / par-dessus l'épaule : rapproche la caméra quand un mur s'interpose entre elle et Harry. Désactivé = la caméra peut traverser les murs.", "Third-Person / Über die Schulter: zieht die Kamera heran, wenn eine Wand zwischen ihr und Harry liegt. Aus = die Kamera kann durch Wände gehen.", "Terza persona / sopra la spalla: avvicina la telecamera quando un muro si frappone tra essa e Harry. Disattivato = la telecamera può attraversare i muri.", "三人称/肩越し: カメラとハリーの間に壁が入るとカメラを寄せます。オフ = カメラが壁をすり抜けます。", "第三人称/越肩视角: 当墙壁挡在镜头和 Harry 之间时拉近镜头。关闭 = 镜头可以穿墙。", "От 3-го лица / из-за плеча: приближает камеру, когда между ней и Гарри оказывается стена. Выкл. = камера может проходить сквозь стены.", "Trzecia osoba / zza ramienia: przybliża kamerę, gdy ściana znajdzie się między nią a Harrym. Wył. = kamera może przenikać przez ściany." } },
            { "Stops the D-pad from moving Harry so it can be bound to actions (dpup / dpdown / dpleft / dpright). Menus and arrow keys are unaffected.",
                new[]{ "Impide que la cruceta mueva a Harry para poder asignarla a acciones (dpup / dpdown / dpleft / dpright). Los menús y las flechas del teclado no se ven afectados.", "Impede que o direcional mova Harry para que possa ser atribuído a ações (dpup / dpdown / dpleft / dpright). Menus e setas do teclado não são afetados.", "Empêche la croix de déplacer Harry pour pouvoir l'assigner à des actions (dpup / dpdown / dpleft / dpright). Menus et flèches du clavier non affectés.", "Verhindert, dass das Steuerkreuz Harry bewegt, damit es Aktionen zugewiesen werden kann (dpup / dpdown / dpleft / dpright). Menüs und Pfeiltasten bleiben unberührt.", "Impedisce alla croce direzionale di muovere Harry così da poterla assegnare ad azioni (dpup / dpdown / dpleft / dpright). Menu e frecce della tastiera non cambiano.", "十字キーでハリーが動かないようにし、アクションに割り当てられるようにします(dpup / dpdown / dpleft / dpright)。メニューとキーボードの矢印キーには影響しません。", "让方向键不再移动 Harry，以便绑定到动作(dpup / dpdown / dpleft / dpright)。菜单和键盘方向键不受影响。", "Отключает движение Гарри крестовиной, чтобы её можно было назначить на действия (dpup / dpdown / dpleft / dpright). Меню и стрелки клавиатуры не затрагиваются.", "Wyłącza poruszanie Harrym krzyżakiem, aby można go było przypisać do akcji (dpup / dpdown / dpleft / dpright). Menu i strzałki klawiatury bez zmian." } },
            { "Thirdperson / Over-the-Shoulder only: shots near an enemy snap onto its body — light with the mouse, stronger on a controller. Off = shots go exactly where you aim.",
                new[]{ "Solo 3ª persona / sobre el hombro: los disparos cerca de un enemigo se ajustan a su cuerpo; leve con ratón, más fuerte con mando. Desactivado = los disparos van justo donde apuntas.", "Só 3ª pessoa / sobre o ombro: tiros perto de um inimigo se ajustam ao corpo dele — leve no mouse, mais forte no controle. Desligado = os tiros vão exatamente para onde você mira.", "3e personne / par-dessus l'épaule uniquement : les tirs proches d'un ennemi s'accrochent à son corps — léger à la souris, plus fort à la manette. Désactivé = les tirs vont exactement où vous visez.", "Nur Third-Person / Über die Schulter: Schüsse nahe einem Gegner rasten auf dessen Körper ein — leicht mit Maus, stärker mit Controller. Aus = Schüsse gehen genau dorthin, wo Sie zielen.", "Solo terza persona / sopra la spalla: i colpi vicini a un nemico si agganciano al suo corpo — leggero con il mouse, più forte col controller. Disattivato = i colpi vanno esattamente dove miri.", "三人称/肩越しのみ: 敵の近くへの射撃が敵の体に吸着します(マウスでは弱め、コントローラーでは強め)。オフ = 狙った場所に正確に撃ちます。", "仅限第三人称/越肩视角: 敌人附近的射击会吸附到其身上 — 鼠标较弱，手柄较强。关闭 = 子弹准确飞向瞄准点。", "Только от 3-го лица / из-за плеча: выстрелы рядом с врагом притягиваются к его телу — слабо для мыши, сильнее для геймпада. Выкл. = выстрелы идут точно в точку прицела.", "Tylko trzecia osoba / zza ramienia: strzały obok wroga przyciągają się do jego ciała — lekko przy myszy, mocniej na kontrolerze. Wył. = strzały lecą dokładnie tam, gdzie celujesz." } },
            { "Classic = original fixed cameras. Thirdperson Shooter = follow camera behind Harry. Over the Shoulder = the same, offset to one side (middle mouse swaps sides).",
                new[]{ "Clásico = cámaras fijas originales. Disparos en 3ª persona = cámara que sigue a Harry por detrás. Sobre el hombro = lo mismo, desplazada a un lado (el botón central del ratón cambia de lado).", "Clássico = câmeras fixas originais. Tiro em 3ª pessoa = câmera que segue Harry por trás. Sobre o ombro = o mesmo, deslocada para um lado (botão do meio do mouse troca o lado).", "Classique = caméras fixes d'origine. Tir à la 3e personne = caméra qui suit Harry par derrière. Par-dessus l'épaule = idem, décalée sur un côté (clic molette pour changer de côté).", "Klassisch = originale feste Kameras. Third-Person-Shooter = Verfolgerkamera hinter Harry. Über die Schulter = dasselbe, seitlich versetzt (mittlere Maustaste wechselt die Seite).", "Classico = telecamere fisse originali. Sparatutto in 3a persona = telecamera che segue Harry da dietro. Sopra la spalla = lo stesso, spostata su un lato (il tasto centrale del mouse cambia lato).", "クラシック = 本来の固定カメラ。三人称シューター = ハリーの背後を追うカメラ。肩越し = 同じく片側に寄せたもの(マウス中ボタンで左右切替)。", "经典 = 原版固定镜头。第三人称射击 = 跟随在 Harry 身后的镜头。越肩视角 = 同上但偏向一侧(鼠标中键切换左右)。", "Классика = оригинальные фиксированные камеры. Шутер от 3-го лица = камера следует за Гарри сзади. Из-за плеча = то же, со смещением вбок (средняя кнопка мыши меняет сторону).", "Klasyczny = oryginalne stałe kamery. Strzelanka TPP = kamera podążająca za Harrym. Zza ramienia = to samo, przesunięte w bok (środkowy przycisk myszy zmienia stronę)." } },
            { "Thirdperson only: aiming eases the camera over Harry's shoulder, and back when you lower the gun.",
                new[]{ "Solo 3ª persona: al apuntar, la cámara se desliza sobre el hombro de Harry y vuelve al bajar el arma.", "Só 3ª pessoa: ao mirar, a câmera desliza para o ombro de Harry e volta quando você abaixa a arma.", "3e personne uniquement : viser fait glisser la caméra au-dessus de l'épaule de Harry, puis elle revient quand vous baissez l'arme.", "Nur Third-Person: Beim Zielen gleitet die Kamera über Harrys Schulter und beim Senken der Waffe zurück.", "Solo terza persona: mirando, la telecamera scivola sopra la spalla di Harry e torna indietro quando abbassi l'arma.", "三人称のみ: 構えるとカメラがハリーの肩越しに移動し、銃を下ろすと戻ります。", "仅限第三人称: 瞄准时镜头平滑移到 Harry 肩后，放下枪时再移回。", "Только от 3-го лица: при прицеливании камера плавно уходит за плечо Гарри и возвращается, когда вы опускаете оружие.", "Tylko trzecia osoba: podczas celowania kamera płynnie przechodzi za ramię Harry'ego i wraca po opuszczeniu broni." } },
            { "Shows a crosshair while aiming in Thirdperson / Over-the-Shoulder.",
                new[]{ "Muestra una retícula al apuntar en 3ª persona / sobre el hombro.", "Mostra uma mira ao mirar em 3ª pessoa / sobre o ombro.", "Affiche un réticule pendant la visée en 3e personne / par-dessus l'épaule.", "Zeigt beim Zielen in Third-Person / Über die Schulter ein Fadenkreuz.", "Mostra un mirino mentre miri in terza persona / sopra la spalla.", "三人称/肩越しで構えているときに照準を表示します。", "在第三人称/越肩视角瞄准时显示准星。", "Показывает прицел при прицеливании от 3-го лица / из-за плеча.", "Pokazuje celownik podczas celowania w trzeciej osobie / zza ramienia." } },
            { "Crosshair shape. In game, Backspace cycles through the styles and off.",
                new[]{ "Forma de la retícula. En el juego, Retroceso alterna entre los estilos y desactivada.", "Formato da mira. No jogo, Backspace alterna entre os estilos e desligada.", "Forme du réticule. En jeu, Retour arrière fait défiler les styles et la désactivation.", "Form des Fadenkreuzes. Im Spiel schaltet die Rücktaste durch die Stile und aus.", "Forma del mirino. In gioco, Backspace scorre tra gli stili e lo spegnimento.", "照準の形。ゲーム中はBackspaceで各スタイルとオフを切り替えます。", "准星形状。游戏中按 Backspace 可在各样式和关闭之间切换。", "Форма прицела. В игре Backspace перебирает стили и выключение.", "Kształt celownika. W grze Backspace przełącza style i wyłączenie." } },
            // ---- main window: message boxes ----
            { "No Silent Hill disc image found.\n\nPlease put a Silent Hill .bin (USA or PAL/European release)\nin the gamedata folder!",
                new[]{ "No se encontró ninguna imagen de disco de Silent Hill.\n\nPon un .bin de Silent Hill (versión USA o PAL/europea)\nen la carpeta gamedata.", "Nenhuma imagem de disco de Silent Hill encontrada.\n\nColoque um .bin de Silent Hill (versão USA ou PAL/europeia)\nna pasta gamedata!", "Aucune image disque de Silent Hill trouvée.\n\nPlacez un .bin de Silent Hill (version USA ou PAL/européenne)\ndans le dossier gamedata !", "Kein Silent-Hill-Disc-Image gefunden.\n\nBitte legen Sie eine Silent-Hill-.bin (USA- oder PAL/Europa-Version)\nin den Ordner gamedata!", "Nessuna immagine disco di Silent Hill trovata.\n\nMetti un .bin di Silent Hill (versione USA o PAL/europea)\nnella cartella gamedata!", "Silent Hillのディスクイメージが見つかりません。\n\nSilent Hillの.bin(USA版またはPAL/ヨーロッパ版)を\ngamedataフォルダに置いてください。", "未找到 Silent Hill 光盘镜像。\n\n请将 Silent Hill 的 .bin(美版或 PAL/欧版)\n放入 gamedata 文件夹!", "Образ диска Silent Hill не найден.\n\nПоложите .bin Silent Hill (версия USA или PAL/европейская)\nв папку gamedata!", "Nie znaleziono obrazu płyty Silent Hill.\n\nUmieść plik .bin Silent Hill (wersja USA lub PAL/europejska)\nw folderze gamedata!" } },
            { "SilentHillPC.exe not found.",
                new[]{ "No se encontró SilentHillPC.exe.", "SilentHillPC.exe não encontrado.", "SilentHillPC.exe introuvable.", "SilentHillPC.exe nicht gefunden.", "SilentHillPC.exe non trovato.", "SilentHillPC.exeが見つかりません。", "未找到 SilentHillPC.exe。", "SilentHillPC.exe не найден.", "Nie znaleziono SilentHillPC.exe." } },
