                new[]{ "¡Está todo al día!\n\nOrigen: {0}\nÚltima: {1}", "Você está atualizado!\n\nOrigem: {0}\nMais recente: {1}", "Vous êtes à jour !\n\nSource : {0}\nDernière : {1}", "Sie sind auf dem neuesten Stand!\n\nQuelle: {0}\nNeueste: {1}", "Sei aggiornato!\n\nOrigine: {0}\nUltima: {1}", "最新の状態です!\n\n取得元: {0}\n最新: {1}", "已是最新版本!\n\n来源: {0}\n最新: {1}", "У вас последняя версия!\n\nИсточник: {0}\nПоследняя: {1}", "Masz najnowszą wersję!\n\nŹródło: {0}\nNajnowsza: {1}" } },
